<?php $rows=$pdo->query('SELECT g.*,u.unit_code,u.current_meter,u.meter_type FROM grease_records g JOIN units u ON u.id=g.unit_id ORDER BY grease_date DESC')->fetchAll();$units=$pdo->query('SELECT id,unit_code,current_meter FROM units ORDER BY unit_code')->fetchAll();?>
<div class="card panel"><h3>Input Grease</h3><form class="form-grid compact" method="post" action="actions/save_grease.php"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><label>Unit<select name="unit_id"><?php foreach($units as $u):?><option value="<?=$u['id']?>"><?=e($u['unit_code'])?></option><?php endforeach;?></select></label><label>Tanggal<input type="date" name="grease_date" value="<?=date('Y-m-d')?>"></label><label>Meter Saat Grease<input type="number" step="0.1" name="meter_at_grease"></label><label>Interval<input type="number" name="interval_meter" value="200"></label><label>Status<select name="status"><?php foreach(['Sesuai Jadwal','Jatuh Tempo','Terlambat','Belum Ada Data'] as $s):?><option><?=$s?></option><?php endforeach;?></select></label><label>Petugas<input name="performed_by"></label><label>Catatan<input name="notes"></label><div><button class="btn primary">Simpan</button></div></form></div>
<div class="card panel"><h3>Status Grease</h3><table><thead><tr><th>Tanggal</th><th>Unit</th><th>Meter Grease</th><th>Meter Aktual</th><th>Interval</th><th>Status</th><th>Petugas</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['grease_date'])?></td><td><?=e($r['unit_code'])?></td><td><?=number_format($r['meter_at_grease'],0,',','.')?></td><td><?=number_format($r['current_meter'],0,',','.')?></td><td><?=$r['interval_meter']?></td><td><span class="status <?=status_class($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e($r['performed_by'])?></td></tr><?php endforeach;?></tbody></table></div>
